//! [`CocoEval`] (the full COCOeval port) against pycocotools' twelve `COCOeval.stats` on every fixture in
//! `tests/fixtures/coco/` (no crowd, area = box area) and `tests/fixtures/coco_full/` (crowd regions and annotation
//! areas, truths `[x1, y1, x2, y2, class, iscrowd, area]`), all generated by `bench/parity/coco_reference.py`.
//! Image `i` is COCO image id `i + 1`, as in the script.

use folo_vision::cocoeval::{CocoEval, CocoTruth};
use folo_vision::{Detection, Xyxy};
use serde_json::Value;
use std::path::Path;

/// pycocotools averages with numpy (pairwise summation) and CocoEval in another order: only rounding differs.
const TOL: f64 = 1e-12;

fn f32_of(v: &Value) -> f32 {
    v.as_f64().expect("number") as f32
}

fn bbox(b: &[Value]) -> Xyxy {
    Xyxy { x1: f32_of(&b[0]), y1: f32_of(&b[1]), x2: f32_of(&b[2]), y2: f32_of(&b[3]) }
}

fn run(path: &Path) -> Result<(), String> {
    let v: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let nc = v["num_classes"].as_u64().unwrap() as usize;
    let mut ev = CocoEval::new(nc);
    for (i, im) in v["images"].as_array().unwrap().iter().enumerate() {
        let dets: Vec<Detection> = im["preds"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| {
                let p = p.as_array().unwrap();
                Detection { bbox: bbox(p), score: f32_of(&p[4]), class: p[5].as_u64().unwrap() as u32 }
            })
            .collect();
        let truths: Vec<CocoTruth> = im["truths"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| {
                let t = t.as_array().unwrap();
                let b = bbox(t);
                let class = t[4].as_u64().unwrap() as u32;
                if t.len() > 5 {
                    CocoTruth {
                        iscrowd: t[5].as_u64().unwrap() == 1,
                        area: t[6].as_f64().unwrap(),
                        ..CocoTruth::from_box(b, class)
                    }
                } else {
                    CocoTruth::from_box(b, class)
                }
            })
            .collect();
        ev.add_image(i as u64 + 1, &dets, &truths);
    }
    let got = ev.compute().as_array();
    let want: Vec<f64> = v["coco"]["stats"].as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
    let names = v["coco"]["stat_names"].as_array().unwrap();
    let mut bad = Vec::new();
    for (k, (g, w)) in got.iter().zip(&want).enumerate() {
        if (g - w).abs() > TOL {
            bad.push(format!("{} {g} vs pycocotools {w}", names[k].as_str().unwrap()));
        }
    }
    println!("{:24} {}", v["name"].as_str().unwrap(), got.map(|x| format!("{x:.4}")).join(" "));
    if bad.is_empty() { Ok(()) } else { Err(format!("{}: {}", path.display(), bad.join(", "))) }
}

#[test]
fn twelve_stats_match_pycocotools() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures");
    let mut paths = Vec::new();
    for dir in ["coco", "coco_full"] {
        let mut p: Vec<_> = std::fs::read_dir(root.join(dir)).unwrap().map(|e| e.unwrap().path()).collect();
        p.sort();
        paths.extend(p);
    }
    assert!(paths.len() >= 27, "fixtures missing: {}", paths.len());
    let failures: Vec<String> = paths.iter().filter_map(|p| run(p).err()).collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
